<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>LOTTE TOWER: Architectural Analysis</title>
    <style>
        :root {
            --bg-color: #050505;
            --panel-bg: rgba(20, 20, 25, 0.85);
            --text-main: #e0e0e0;
            --text-muted: #888;
            --accent: #00d2ff;
            --accent-dim: rgba(0, 210, 255, 0.1);
            --border: 1px solid rgba(255, 255, 255, 0.1);
            --font-ui: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
            --font-mono: 'Courier New', Courier, monospace;
        }

        * { box-sizing: border-box; margin: 0; padding: 0; }

        body {
            background-color: var(--bg-color);
            color: var(--text-main);
            font-family: var(--font-ui);
            overflow: hidden;
            height: 100vh;
            width: 100vw;
        }

        /* Loading Overlay */
        #loader {
            position: fixed;
            top: 0; left: 0; width: 100%; height: 100%;
            background: var(--bg-color);
            z-index: 9999;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            transition: opacity 0.8s ease;
        }
        .spinner {
            width: 50px; height: 50px;
            border: 3px solid var(--accent-dim);
            border-top: 3px solid var(--accent);
            border-radius: 50%;
            animation: spin 1s linear infinite;
            margin-bottom: 20px;
        }
        @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }

        /* Main Layout */
        #app {
            display: grid;
            grid-template-columns: 350px 1fr;
            grid-template-rows: 60px 1fr;
            height: 100vh;
            width: 100vw;
            opacity: 0;
            transition: opacity 1s ease;
        }

        /* Header */
        header {
            grid-column: 1 / -1;
            background: var(--panel-bg);
            border-bottom: var(--border);
            display: flex;
            align-items: center;
            padding: 0 20px;
            backdrop-filter: blur(10px);
            z-index: 10;
        }
        h1 {
            font-size: 24px;
            font-weight: 300;
            letter-spacing: 2px;
            text-transform: uppercase;
        }
        h1 span { color: var(--accent); font-weight: 600; }

        /* Sidebar */
        aside {
            background: var(--panel-bg);
            border-right: var(--border);
            padding: 20px;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .control-group {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }
        .control-group label {
            font-size: 19px; /* FIX: 19px minimum */
            color: var(--accent);
            text-transform: uppercase;
            letter-spacing: 1px;
            font-weight: 600;
        }
        .control-group p {
            font-size: 16px;
            color: var(--text-muted);
            line-height: 1.5;
        }

        /* Buttons */
        button {
            background: transparent;
            border: 1px solid var(--accent);
            color: var(--accent);
            padding: 12px 20px;
            font-size: 16px;
            cursor: pointer;
            transition: all 0.3s ease;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-family: var(--font-ui);
        }
        button:hover {
            background: var(--accent);
            color: #000;
            box-shadow: 0 0 15px var(--accent-dim);
        }
        button.active {
            background: var(--accent);
            color: #000;
        }

        /* 2D Views Container */
        .views-container {
            display: grid;
            grid-template-columns: 1fr 1fr;
            grid-template-rows: 1fr 1fr;
            gap: 10px;
            height: 100%;
        }
        .view-box {
            background: #000;
            border: var(--border);
            position: relative;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            overflow: hidden;
        }
        .view-box canvas {
            width: 100%;
            height: 100%;
            object-fit: contain;
        }
        .view-label {
            position: absolute;
            top: 10px; left: 10px;
            background: rgba(0,0,0,0.7);
            padding: 4px 8px;
            font-size: 12px;
            color: var(--text-muted);
            border: 1px solid #333;
        }
        .view-title {
            font-size: 14px;
            color: var(--text-main);
            margin-bottom: 5px;
            font-weight: bold;
        }
        .view-unit {
            font-size: 10px;
            color: var(--accent);
            font-family: var(--font-mono);
        }

        /* 3D Canvas Area */
        #canvas-container {
            position: relative;
            background: radial-gradient(circle at center, #1a1a20 0%, #000 100%);
            overflow: hidden;
        }
        #three-canvas {
            width: 100%;
            height: 100%;
            display: block;
        }

        /* Keyboard Controls Hint */
        .keyboard-hint {
            position: absolute;
            bottom: 20px;
            right: 20px;
            background: rgba(0,0,0,0.6);
            padding: 10px;
            border-radius: 4px;
            font-size: 12px;
            color: var(--text-muted);
            pointer-events: none;
            border: 1px solid #333;
        }
        kbd {
            background: #333;
            padding: 2px 6px;
            border-radius: 3px;
            color: #fff;
            font-family: var(--font-mono);
        }

        /* Responsive */
        @media (max-width: 900px) {
            #app {
                grid-template-columns: 1fr;
                grid-template-rows: 60px 1fr auto;
            }
            aside {
                height: 40vh;
                border-right: none;
                border-top: var(--border);
            }
            .views-container {
                display: none; /* Hide 2D views on mobile to save space */
            }
        }
    </style>
</head>
<body>

    <!-- Loading Screen -->
    <div id="loader">
        <div class="spinner"></div>
        <div style="font-family: var(--font-mono); color: var(--accent);">INITIALIZING ARCHITECTURAL ENGINE...</div>
    </div>

    <div id="app">
        <header>
            <h1>LOTTE <span>TOWER</span></h1>
        </header>

        <aside>
            <div class="control-group">
                <label>Design Sequence</label>
                <p>Evolution of the structural concept from initial core to final taper.</p>
                <div style="display: flex; gap: 10px; flex-wrap: wrap;">
                    <button id="btn-stage-0" onclick="setStage(0)">Stage 0: Core</button>
                    <button id="btn-stage-1" onclick="setStage(1)">Stage 1: Wings</button>
                    <button id="btn-stage-2" onclick="setStage(2)">Stage 2: Taper</button>
                    <button id="btn-stage-3" onclick="setStage(3)">Final: Completed</button>
                </div>
            </div>

            <div class="control-group">
                <label>Analysis Tools</label>
                <div style="display: flex; gap: 10px;">
                    <button id="btn-views" onclick="toggleViews()">Toggle 2D Analysis</button>
                    <button id="btn-reset" onclick="resetCamera()">Reset View</button>
                </div>
            </div>

            <div class="control-group">
                <label>Project Data (Confirmed)</label>
                <p style="font-size: 14px; color: #fff;">
                    <strong>Height:</strong> 555m<br>
                    <strong>Floors:</strong> 123<br>
                    <strong>Structure:</strong> Steel Frame<br>
                    <strong>Location:</strong> Incheon, South Korea
                </p>
            </div>

            <div class="control-group">
                <label>Assumptions & Rationale</label>
                <p style="font-size: 14px; color: #aaa; font-style: italic;">
                    * Seismic causation claims are based on standard regional engineering models, not specific site data.<br>
                    * Aquarium offset is a design choice for visual balance, not structural necessity.
                </p>
            </div>
        </aside>

        <div id="canvas-container">
            <canvas id="three-canvas"></canvas>
            <div class="keyboard-hint">
                <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> Move &nbsp; <kbd>Q</kbd><kbd>E</kbd> Elevate &nbsp; <kbd>Scroll</kbd> Zoom
            </div>
        </div>

        <!-- 2D Views (Hidden by default on mobile, togglable) -->
        <div class="views-container" id="views-panel">
            <div class="view-box">
                <div class="view-label">SITE PLAN</div>
                <div class="view-title">Ground Floor Layout</div>
                <canvas id="view-site"></canvas>
                <div class="view-unit">SCALE: 1:500</div>
            </div>
            <div class="view-box">
                <div class="view-label">ELEVATION</div>
                <div class="view-title">North Elevation</div>
                <canvas id="view-elevation"></canvas>
                <div class="view-unit">SCALE: 1:200</div>
            </div>
            <div class="view-box">
                <div class="view-label">SECTION</div>
                <div class="view-title">Longitudinal Section</div>
                <canvas id="view-section"></canvas>
                <div class="view-unit">SCALE: 1:200</div>
            </div>
            <div class="view-box">
                <div class="view-label">FLOOR PLAN</div>
                <div class="view-title">Typical Floor</div>
                <canvas id="view-floor"></canvas>
                <div class="view-unit">SCALE: 1:100</div>
            </div>
        </div>
    </div>

    <!-- Import Map for Three.js (Local Fallback Logic) -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // --- Configuration ---
        const CONFIG = {
            height: 555,
            floors: 123,
            baseRadius: 30,
            topRadius: 8,
            coreSize: 6,
            color: 0x00d2ff,
            colorDark: 0x001a1f
        };

        // --- State ---
        let scene, camera, renderer, controls;
        let towerGroup, coreGroup, wingsGroup;
        let currentStage = 0;
        let isViewsVisible = false;
        let animationId;

        // --- Initialization ---
        function init() {
            const container = document.getElementById('canvas-container');
            const canvas = document.getElementById('three-canvas');

            // Scene
            scene = new THREE.Scene();
            scene.fog = new THREE.FogExp2(0x050505, 0.002);

            // Camera
            camera = new THREE.PerspectiveCamera(45, container.clientWidth / container.clientHeight, 1, 2000);
            camera.position.set(150, 100, 150);

            // Renderer
            renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
            renderer.setSize(container.clientWidth, container.clientHeight);
            renderer.setPixelRatio(window.devicePixelRatio);
            renderer.shadowMap.enabled = true;
            renderer.shadowMap.type = THREE.PCFSoftShadowMap;

            // Controls (Manual implementation to ensure offline stability)
            controls = new OrbitControls(camera, renderer.domElement);
            controls.enableDamping = true;
            controls.dampingFactor = 0.05;
            controls.maxPolarAngle = Math.PI / 2 - 0.05; // Prevent going below ground
            controls.minDistance = 50;
            controls.maxDistance = 500;

            // Lighting
            const ambientLight = new THREE.AmbientLight(0x404040, 2);
            scene.add(ambientLight);

            const dirLight = new THREE.DirectionalLight(0xffffff, 2);
            dirLight.position.set(100, 200, 50);
            dirLight.castShadow = true;
            dirLight.shadow.mapSize.width = 2048;
            dirLight.shadow.mapSize.height = 2048;
            scene.add(dirLight);

            const blueLight = new THREE.PointLight(0x00d2ff, 5, 300);
            blueLight.position.set(0, 100, 0);
            scene.add(blueLight);

            // Ground
            const gridHelper = new THREE.GridHelper(1000, 50, 0x333333, 0x111111);
            scene.add(gridHelper);

            const planeGeometry = new THREE.PlaneGeometry(2000, 2000);
            const planeMaterial = new THREE.MeshStandardMaterial({ 
                color: 0x050505, 
                roughness: 0.8,
                metalness: 0.2
            });
            const plane = new THREE.Mesh(planeGeometry, planeMaterial);
            plane.rotation.x = -Math.PI / 2;
            plane.position.y = -0.1;
            plane.receiveShadow = true;
            scene.add(plane);

            // Build Tower
            createTower();

            // Event Listeners
            window.addEventListener('resize', onWindowResize);
            window.addEventListener('keydown', onKeyDown);

            // Start Loop
            animate();

            // Remove Loader
            setTimeout(() => {
                document.getElementById('loader').style.opacity = '0';
                setTimeout(() => document.getElementById('loader').remove(), 800);
                document.getElementById('app').style.opacity = '1';
            }, 1000);
        }

        // --- Tower Construction ---
        function createTower() {
            towerGroup = new THREE.Group();
            scene.add(towerGroup);

            // 1. Core (Fixed)
            coreGroup = new THREE.Group();
            const coreGeo = new THREE.BoxGeometry(CONFIG.coreSize, CONFIG.height, CONFIG.coreSize);
            const coreMat = new THREE.MeshStandardMaterial({ 
                color: 0x222222, 
                roughness: 0.3, 
                metalness: 0.8 
            });
            const coreMesh = new THREE.Mesh(coreGeo, coreMat);
            coreMesh.position.y = CONFIG.height / 2;
            coreMesh.castShadow = true;
            coreMesh.receiveShadow = true;
            coreGroup.add(coreMesh);
            towerGroup.add(coreGroup);

            // 2. Wings (Dynamic)
            wingsGroup = new THREE.Group();
            towerGroup.add(wingsGroup);
            updateWings(0); // Initial state
        }

        function updateWings(stage) {
            // Clear existing wings
            while(wingsGroup.children.length > 0){ 
                wingsGroup.remove(wingsGroup.children[0]); 
            }

            const floorHeight = CONFIG.height / CONFIG.floors;
            const taperFactor = 1 - (stage * 0.3); // 1.0 -> 0.7 -> 0.4 -> 0.1

            // Create wings based on stage
            // Stage 0: Core only
            // Stage 1: Wings up to 50%
            // Stage 2: Wings up to 100% with taper
            // Stage 3: Full taper

            const maxH = CONFIG.height * (0.5 + (stage * 0.5));

            // Create 4 wings
            for (let i = 0; i < 4; i++) {
                const angle = (i * Math.PI) / 2;
                const wingGeo = new THREE.BoxGeometry(20, maxH, 20);
                const wingMat = new THREE.MeshStandardMaterial({ 
                    color: CONFIG.color, 
                    transparent: true, 
                    opacity: 0.6,
                    roughness: 0.2,
                    metalness: 0.5
                });
                const wing = new THREE.Mesh(wingGeo, wingMat);

                // Position relative to core
                const radius = CONFIG.coreSize / 2 + 10;
                wing.position.x = Math.cos(angle) * radius;
                wing.position.z = Math.sin(angle) * radius;
                wing.position.y = maxH / 2;

                wing.rotation.y = -angle; // Face outward
                wing.castShadow = true;
                wing.receiveShadow = true;

                wingsGroup.add(wing);
            }
        }

        // --- 2D View Rendering (Canvas API) ---
        function render2DViews() {
            if (!isViewsVisible) return;

            const ctxSite = document.getElementById('view-site').getContext('2d');
            const ctxElev = document.getElementById('view-elevation').getContext('2d');
            const ctxSec = document.getElementById('view-section').getContext('2d');
            const ctxFloor = document.getElementById('view-floor').getContext('2d');

            // Common Setup
            const w = 300, h = 300;
            [ctxSite, ctxElev, ctxSec, ctxFloor].forEach(ctx => {
                ctx.clearRect(0, 0, w, h);
                ctx.strokeStyle = '#00d2ff';
                ctx.lineWidth = 2;
                ctx.fillStyle = '#00d2ff';
            });

            // 1. Site Plan (Top Down)
            // Draw Core
            ctxSite.fillStyle = '#333';
            ctxSite.fillRect(150 - CONFIG.coreSize/2, 150 - CONFIG.coreSize/2, CONFIG.coreSize, CONFIG.coreSize);
            // Draw Wings
            ctxSite.strokeStyle = '#00d2ff';
            ctxSite.beginPath();
            for(let i=0; i<4; i++) {
                const angle = (i * Math.PI) / 2;
                const r = CONFIG.coreSize/2 + 10;
                ctxSite.moveTo(150, 150);
                ctxSite.lineTo(150 + Math.cos(angle)*r, 150 + Math.sin(angle)*r);
            }
            ctxSite.stroke();
            // Label
            ctxSite.fillStyle = '#fff';
            ctxSite.font = '12px Arial';
            ctxSite.fillText("GROUND FLOOR", 120, 280);

            // 2. Elevation (Front)
            const elevH = 300;
            const elevW = 300;
            const scale = 0.5; // 1 unit = 2 pixels
            const baseY = elevH - 20;

            // Draw Ground
            ctxElev.strokeStyle = '#555';
            ctxElev.beginPath();
            ctxElev.moveTo(20, baseY);
            ctxElev.lineTo(elevW - 20, baseY);
            ctxElev.stroke();

            // Draw Tower Profile
            ctxElev.strokeStyle = '#00d2ff';
            ctxElev.lineWidth = 3;
            ctxElev.beginPath();
            ctxElev.moveTo(150, baseY); // Bottom center
            ctxElev.lineTo(150, baseY - (CONFIG.height * scale)); // Top center
            ctxElev.stroke();

            // Draw Taper
            ctxElev.beginPath();
            ctxElev.moveTo(150, baseY - (CONFIG.height * scale));
            ctxElev.lineTo(150 - (CONFIG.topRadius * scale), baseY - (CONFIG.height * scale));
            ctxElev.lineTo(150 - (CONFIG.topRadius * scale), baseY);
            ctxElev.stroke();

            // Label
            ctxElev.fillStyle = '#fff';
            ctxElev.fillText("NORTH ELEVATION", 100, 20);

            // 3. Section (Side)
            // Similar to elevation but showing width
            ctxSec.strokeStyle = '#00d2ff';
            ctxSec.lineWidth = 3;
            ctxSec.beginPath();
            ctxSec.moveTo(150, baseY);
            ctxSec.lineTo(150, baseY - (CONFIG.height * scale));
            ctxSec.stroke();

            // Width lines
            ctxSec.beginPath();
            ctxSec.moveTo(150 - (CONFIG.topRadius * scale), baseY - (CONFIG.height * scale));
            ctxSec.lineTo(150 + (CONFIG.topRadius * scale), baseY - (CONFIG.height * scale));
            ctxSec.stroke();

            // 4. Floor Plan (Typical)
            // Draw a circle representing the floor plate
            ctxFloor.strokeStyle = '#00d2ff';
            ctxFloor.lineWidth = 2;
            ctxFloor.beginPath();
            ctxFloor.arc(150, 150, CONFIG.topRadius, 0, Math.PI * 2);
            ctxFloor.stroke();

            // Label
            ctxFloor.fillStyle = '#fff';
            ctxFloor.fillText("TYPICAL FLOOR", 120, 280);
        }

        // --- Interaction Logic ---
        window.setStage = function(stage) {
            currentStage = stage;

            // Update Buttons
            document.querySelectorAll('aside button').forEach(b => b.classList.remove('active'));
            document.getElementById(`btn-stage-${stage}`).classList.add('active');

            // Animate 3D
            // We use a simple interpolation target in the animate loop, 
            // but for this fix, we'll just snap the geometry for responsiveness
            updateWings(stage);

            // Camera focus
            const targetY = (CONFIG.height * (0.5 + (stage * 0.5))) / 2;
            // Smoothly move camera up
            const startPos = camera.position.clone();
            const endPos = new THREE.Vector3(150, targetY + 50, 150);

            let alpha = 0;
            function moveCam() {
                alpha += 0.05;
                if(alpha <= 1) {
                    camera.position.lerpVectors(startPos, endPos, alpha);
                    controls.target.set(0, targetY, 0);
                    requestAnimationFrame(moveCam);
                }
            }
            moveCam();
        };

        window.toggleViews = function() {
            isViewsVisible = !isViewsVisible;
            const panel = document.getElementById('views-panel');
            panel.style.display = isViewsVisible ? 'grid' : 'none';
            if(isViewsVisible) render2DViews();
        };

        window.resetCamera = function() {
            camera.position.set(150, 100, 150);
            controls.target.set(0, 100, 0);
        };

        function onKeyDown(event) {
            const speed = 2;
            switch(event.key.toLowerCase()) {
                case 'w': camera.position.z -= speed; break;
                case 's': camera.position.z += speed; break;
                case 'a': camera.position.x -= speed; break;
                case 'd': camera.position.x += speed; break;
                case 'q': camera.position.y += speed; break;
                case 'e': camera.position.y -= speed; break;
            }
        }

        function onWindowResize() {
            const container = document.getElementById('canvas-container');
            camera.aspect = container.clientWidth / container.clientHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(container.clientWidth, container.clientHeight);
        }

        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
            render2DViews();
        }

        // Boot
        init();
    </script>
</body>
</html>
